-- 1. KATEGORİLER (3 Adet)
SELECT setval('categories_id_seq', (SELECT COALESCE(MAX(id), 1) FROM categories));

-- 2. ÜRÜNLER VE FİYATLAR (20 Adet)
SELECT setval('products_id_seq', (SELECT COALESCE(MAX(id), 1) FROM products));

-- 3. MASALAR (30 Adet)
SELECT setval('tables_id_seq', (SELECT COALESCE(MAX(id), 1) FROM tables));

-- 4. ESNAFLAR VE VERESİYE BAKİYELERİ (5 Adet)
SELECT setval('merchants_id_seq', (SELECT COALESCE(MAX(id), 1) FROM merchants));

-- 5. ESNAF ÇETELE HAREKETLERİ (5 Adet)
SELECT setval('merchant_transactions_id_seq', (SELECT COALESCE(MAX(id), 1) FROM merchant_transactions));

-- 6. GARSONLAR (4 Adet)
SELECT setval('waiters_id_seq', (SELECT COALESCE(MAX(id), 1) FROM waiters));

-- 7. KASA VE ÖDEMELER GEÇMİŞİ (2 Adet)
SELECT setval('payments_id_seq', (SELECT COALESCE(MAX(id), 1) FROM payments));

-- 8. SİPARİŞLER (6 Adet)
SELECT setval('orders_id_seq', (SELECT COALESCE(MAX(id), 1) FROM orders));

-- 9. SİPARİŞ KALEMLERİ (8 Adet)
SELECT setval('order_items_id_seq', (SELECT COALESCE(MAX(id), 1) FROM order_items));

